#[tokio::test]
async fn test_store_api_get_grouped_categories_typed_leaves() {
    let api = new_store_api_for_mock(
        200,
        "application/json",
        r#"[{"a":{"id":1,"name":"Dogs"}},{"b":{"id":2,"name":"Cats"}}]"#,
    );

    let result = api
        .get_grouped_categories()
        .await
        .expect("GetGroupedCategories failed");

    let first: &Category = result[0].get("a").expect("expected key `a` in first map");
    assert_eq!(first.id, Some(1), "leaf id mismatch");
    assert_eq!(first.name, Some("Dogs".to_string()), "leaf name mismatch");
}

// Nested containers and named enums decode into their typed leaves: a matrix of
// integers, a named enum, arrays of maps of enums and of timestamps, and a
// self-referencing model.
#[tokio::test]
async fn test_store_api_nested_container_responses_decode_into_typed_leaves() {
    let api = new_store_api_for_mock(200, "application/json", "[[1,2],[3]]");
    assert_eq!(
        api.get_matrix().await.expect("get_matrix failed"),
        vec![vec![1, 2], vec![3]]
    );

    let api = new_store_api_for_mock(200, "application/json", r#""green""#);
    assert_eq!(
        api.get_swatch().await.expect("get_swatch failed"),
        Swatch::Green
    );

    let api = new_store_api_for_mock(200, "application/json", r#"[{"a":"red"},{"b":"blue"}]"#);
    let groups = api
        .get_swatch_groups()
        .await
        .expect("get_swatch_groups failed");
    assert_eq!(groups.len(), 2);
    assert_eq!(groups[0].get("a"), Some(&Swatch::Red));
    assert_eq!(groups[1].get("b"), Some(&Swatch::Blue));

    let api = new_store_api_for_mock(
        200,
        "application/json",
        r#"[{"at":"2024-01-15T10:30:00Z"}]"#,
    );
    let stamps = api
        .get_timestamp_groups()
        .await
        .expect("get_timestamp_groups failed");
    assert_eq!(stamps.len(), 1);
    assert!(stamps[0].contains_key("at"));

    let api = new_store_api_for_mock(
        200,
        "application/json",
        r#"{"value":"root","child":{"value":"leaf"}}"#,
    );
    let tree = api.get_tree().await.expect("get_tree failed");
    assert_eq!(tree.value, "root");
    assert_eq!(tree.child.expect("expected a child node").value, "leaf");
}

