/// a header, never as the language's name for the variant.
#[tokio::test]
async fn test_store_api_get_by_swatch_sends_enum_wire_values() {
    let client = Arc::new(RecordingApiClient::new());
    let config = ConfigurationBuilder::new()
        .base_url("http://localhost")
        .build();
    let api = StoreApi::new(client.clone(), config, None);
    let opts = GetBySwatchOptions::new()
        .query_swatch(Swatch::Green)
        .preferred_swatch(Swatch::Blue);

    api.get_by_swatch(Swatch::Red, Some(&opts))
        .await
        .expect("get_by_swatch failed");

    let url = client.url.lock().unwrap().clone();
    assert_eq!(
        url,
        "http://localhost/store/by-swatch/red?querySwatch=green"
    );
    assert_eq!(
        client
            .headers
            .lock()
            .unwrap()
            .get("Preferred-Swatch")
            .map(|s| s.as_str()),
        Some("blue")
    );
}

